// REAL — curriculum, part 2: three more subjects (social studies, health & life skills, technology) and the core
// topics the first part didn't cover (grammar, vocabulary, poetry, shapes, graphs, negative numbers, weather, space,
// plants, matter...). Same format as curriculum.js; merged into it at load. Facts are kept simple, accurate and
// age-appropriate. Every skill has a bank of varied questions; tests/curriculum.test.mjs checks every one.

const ri = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
const pick = (a) => a[Math.floor(Math.random() * a.length)];
const shuffle = (a) => a.map((v) => [Math.random(), v]).sort((x, y) => x[0] - y[0]).map((x) => x[1]);
const doc = (title, lines) => ({ title, lines });
const ch = (skill, q, a, wrong, why, v) => ({ type: 'choice', skill, q, a, o: [a, ...wrong], why, v });
const num = (skill, q, a, why, v, opts = {}) => ({ type: 'number', skill, q, a, why, v, ...opts });
/** a bank of multiple-choice questions: rows of [question, answer, [wrong...], why, visual?] */
const bank = (skill, rows) => () => { const [q, a, w, why, v] = pick(rows); return ch(skill, q, a, w, why, v); };
/** a sort activity built from a random handful of [item, bin] pairs */
const sorter = (skill, q, bins, pairs, why, n = 5) => () => ({ type: 'sort', skill, q, bins, items: shuffle(pairs).slice(0, n), why });


