  'write.grammar': [() => { const s = pick([['The happy dog runs quickly.', { noun: 'dog', verb: 'runs', adjective: 'happy', adverb: 'quickly' }], ['Rosa carefully stacks red apples.', { noun: 'apples', verb: 'stacks', adjective: 'red', adverb: 'carefully' }], ['The tall giraffe eats slowly.', { noun: 'giraffe', verb: 'eats', adjective: 'tall', adverb: 'slowly' }]]); const kind = pick(['noun', 'verb', 'adjective', 'adverb']); const words = Object.values(s[1]); return ch('write.grammar', `In “${s[0]}”, which word is the ${kind}?`, s[1][kind], words.filter((w) => w !== s[1][kind]), `Noun = thing (${s[1].noun}), verb = action (${s[1].verb}), adjective = describes a noun (${s[1].adjective}), adverb = describes how (${s[1].adverb}).`); }],
